// Mock server for an OpenAPI 3.x spec, generated by API To SDK (ZCode). No dependencies.
//   node mock/server.mjs [port]      serves the API from mock/openapi.json on http://127.0.0.1:<port> (default 4010)
// Responses come from the spec's examples (or are synthesised from schemas). Requests are checked against the spec
// (required params, parameter types, JSON body schema) and answered with 400 when they don't match.
// Pick another documented status with the header "Prefer: code=404" (or "X-Mock-Status: 404").
import { createServer } from "node:http";

export function resolveRef(root, ref) {
  if (typeof ref !== "string" || !ref.startsWith("#/")) throw new Error(`Only local $refs are supported: ${ref}`);
  let node = root;
  for (const raw of ref.slice(2).split("/")) { const k = raw.replace(/~1/g, "/").replace(/~0/g, "~"); node = node?.[decodeURIComponent(k)]; if (node === undefined) throw new Error(`Unresolvable $ref ${ref}`); }
  return node;
}
export const deref = (root, node, seen = 0) => { while (node && typeof node === "object" && typeof node.$ref === "string" && seen++ < 50) node = resolveRef(root, node.$ref); return node; };

const typesOf = (s) => (Array.isArray(s.type) ? s.type : s.type ? [s.type] : []).concat(s.nullable ? ["null"] : []);

/** Deterministic example value for a schema. */
export function synth(root, schema, depth = 0, name = "") {
  let s;
  try { s = deref(root, schema); } catch { return null; }
  if (!s || typeof s !== "object" || depth > 8) return null;
  if (s.example !== undefined) return s.example;
  if (Array.isArray(s.examples) && s.examples.length) return s.examples[0];
  if (s.const !== undefined) return s.const;
  if (s.default !== undefined) return s.default;
  if (Array.isArray(s.enum) && s.enum.length) return s.enum[0];
  if (s.allOf) return s.allOf.reduce((acc, p) => { const v = synth(root, p, depth + 1, name); return v && typeof v === "object" && !Array.isArray(v) ? { ...acc, ...v } : acc; }, {});
  if (s.oneOf || s.anyOf) return synth(root, (s.oneOf || s.anyOf)[0], depth + 1, name);
  const t = typesOf(s).filter((x) => x !== "null")[0] || (s.properties ? "object" : s.items ? "array" : undefined);
  switch (t) {
    case "object": {
      const o = {};
      for (const [k, v] of Object.entries(s.properties || {})) { const val = synth(root, v, depth + 1, k); if (val !== undefined) o[k] = val; }
      return o;
    }
    case "array": return s.items ? [synth(root, s.items, depth + 1, name)] : [];
    case "integer": return s.minimum !== undefined ? Math.ceil(s.minimum) : 1;
    case "number": return s.minimum !== undefined ? s.minimum : 1.5;
    case "boolean": return true;
    case "string": {
      switch (s.format) {
        case "date": return "2026-01-15";
        case "date-time": return "2026-01-15T09:30:00Z";
        case "email": return "user@example.com";
        case "uuid": return "00000000-0000-4000-8000-000000000001";
        case "uri": case "url": return "https://example.com/";
        case "binary": return { __blob: true };
        case "byte": return "aGVsbG8=";
        default: return name ? `${name}-example`.slice(0, s.maxLength || 60) : "example";
      }
    }
    default: return null;
  }
}

/** Light JSON-schema check (types, required, enum, const, properties, items, oneOf/anyOf/allOf, additionalProperties, string formats). */
export function check(root, schema, value, path = "body", errs = [], depth = 0) {
  const s = deref(root, schema);
  if (!s || typeof s !== "object" || depth > 20) return errs;
  if (s.allOf) for (const p of s.allOf) check(root, p, value, path, errs, depth + 1);
  if (s.oneOf || s.anyOf) {
    const alts = s.oneOf || s.anyOf;
    const ok = alts.filter((a) => !check(root, a, value, path, [], depth + 1).length).length;
    if (s.oneOf ? ok !== 1 : ok < 1) errs.push(`${path}: matches ${ok} of the ${s.oneOf ? "oneOf" : "anyOf"} alternatives`);
  }
  if (s.const !== undefined && value !== s.const) errs.push(`${path}: must be ${JSON.stringify(s.const)}`);
  if (Array.isArray(s.enum) && !s.enum.includes(value) && !(value === null && typesOf(s).includes("null"))) errs.push(`${path}: must be one of ${s.enum.map((e) => JSON.stringify(e)).join(", ")}`);
  const types = typesOf(s);
  if (types.length) {
    const actual = value === null ? "null" : Array.isArray(value) ? "array" : typeof value === "number" ? (Number.isInteger(value) ? "integer" : "number") : typeof value;
    const okType = types.includes(actual) || (actual === "integer" && types.includes("number"));
    if (!okType) { errs.push(`${path}: expected ${types.join(" | ")}, got ${actual}`); return errs; }
  }
  if (value && typeof value === "object" && !Array.isArray(value) && (s.properties || s.required || s.additionalProperties !== undefined)) {
    for (const r of s.required || []) if (value[r] === undefined) errs.push(`${path}.${r}: required`);
    for (const [k, v] of Object.entries(value)) {
      if (s.properties?.[k]) check(root, s.properties[k], v, `${path}.${k}`, errs, depth + 1);
      else if (s.additionalProperties === false) errs.push(`${path}.${k}: unexpected property`);
      else if (s.additionalProperties && typeof s.additionalProperties === "object") check(root, s.additionalProperties, v, `${path}.${k}`, errs, depth + 1);
    }
  }
  if (Array.isArray(value) && s.items) value.forEach((v, i) => check(root, s.items, v, `${path}[${i}]`, errs, depth + 1));
  if (typeof value === "string") {
    if (s.maxLength !== undefined && value.length > s.maxLength) errs.push(`${path}: longer than ${s.maxLength}`);
    if (s.format === "date" && !/^\d{4}-\d{2}-\d{2}$/.test(value)) errs.push(`${path}: not a date`);
    if (s.format === "date-time" && Number.isNaN(Date.parse(value))) errs.push(`${path}: not a date-time`);
    if (s.format === "email" && !/^[^\s@]+@[^\s@]+$/.test(value)) errs.push(`${path}: not an email`);
    if (s.pattern) { try { if (!new RegExp(s.pattern, "u").test(value)) errs.push(`${path}: does not match ${s.pattern}`); } catch {} }
  }
  if (typeof value === "number") {
    if (s.minimum !== undefined && value < s.minimum) errs.push(`${path}: below minimum ${s.minimum}`);
    if (s.maximum !== undefined && value > s.maximum) errs.push(`${path}: above maximum ${s.maximum}`);
  }
  return errs;
}

const METHODS = ["get", "put", "post", "delete", "options", "head", "patch", "trace"];
export function mediaKind(ct) { const c = String(ct || "").toLowerCase(); if (/json/.test(c)) return "json"; if (c.startsWith("multipart/")) return "multipart"; if (c === "application/x-www-form-urlencoded") return "form"; if (c.startsWith("text/")) return "text"; return "binary"; }

/** First example of a media object (example, examples[0].value, schema example, synthesised). */
export function mediaExample(root, media) {
  if (!media) return undefined;
  if (media.example !== undefined) return media.example;
  if (media.examples && typeof media.examples === "object") { const first = deref(root, Object.values(media.examples)[0]); if (first && first.value !== undefined) return first.value; }
  return media.schema ? synth(root, media.schema) : undefined;
}

function coerce(root, schema, raw) {
  const s = deref(root, schema) || {};
  const t = typesOf(s).filter((x) => x !== "null")[0];
  if (t === "integer") return /^-?\d+$/.test(raw) ? Number(raw) : raw;
  if (t === "number") return raw !== "" && !Number.isNaN(Number(raw)) ? Number(raw) : raw;
  if (t === "boolean") return raw === "true" ? true : raw === "false" ? false : raw;
  return raw;
}

export function createMock(spec, { log = () => {} } = {}) {
  const root = spec;
  const routes = [];
  for (const [p, item0] of Object.entries(spec.paths || {})) {
    const item = deref(root, item0);
    const names = [];
    const re = new RegExp("^" + p.replace(/[.*+?^${}()|[\]\\]/g, (c) => (c === "{" || c === "}" ? c : `\\${c}`)).replace(/\\?\{([^}]+)\\?\}/g, (_, n) => { names.push(n); return "([^/]+)"; }) + "/?$");
    for (const m of METHODS) if (item[m]) routes.push({ path: p, method: m.toUpperCase(), op: item[m], params: [...(item.parameters || []), ...(item[m].parameters || [])].map((x) => deref(root, x)), re, names, literal: p.replace(/\{[^}]+\}/g, "").length });
  }
  routes.sort((a, b) => b.literal - a.literal);
  const calls = [];
  let basePath = "";
  try { basePath = new URL(spec.servers?.[0]?.url ?? "/", "http://mock").pathname.replace(/\/+$/, ""); } catch {}
  const handler = async (req, res) => {
    const url = new URL(req.url, "http://mock");
    if (basePath && (url.pathname === basePath || url.pathname.startsWith(basePath + "/"))) url.pathname = url.pathname.slice(basePath.length) || "/";
    if (req.method === "OPTIONS" && req.headers["access-control-request-method"]) {
      res.writeHead(204, { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Methods": "GET,POST,PUT,PATCH,DELETE,HEAD,OPTIONS", "Access-Control-Allow-Headers": req.headers["access-control-request-headers"] || "*", "Access-Control-Max-Age": "600" });
      return res.end();
    }
    const chunks = []; for await (const c of req) chunks.push(c);
    const raw = Buffer.concat(chunks);
    const send = (status, body, ct = "application/json") => { res.writeHead(status, { "Content-Type": ct, "Access-Control-Allow-Origin": "*" }); res.end(body === undefined ? undefined : ct.includes("json") ? JSON.stringify(body) : String(body)); };
    let route, m;
    for (const r of routes) { if ((m = r.re.exec(url.pathname)) && r.method === req.method) { route = r; break; } }
    if (!route) { const any = routes.some((r) => r.re.test(url.pathname)); log(`${req.method} ${url.pathname} → ${any ? 405 : 404}`); return send(any ? 405 : 404, { code: "mock_no_route", message: `${req.method} ${url.pathname} is not in the spec` }); }
    const errors = [];
    const pathParams = Object.fromEntries(route.names.map((n, i) => [n, decodeURIComponent(m[i + 1])]));
    const query = {};
    for (const p of route.params) {
      let v;
      if (p.in === "path") v = pathParams[p.name];
      else if (p.in === "query") { const all = url.searchParams.getAll(p.name); const s = deref(root, p.schema) || {}; v = typesOf(s).includes("array") ? (all.length ? all : undefined) : all[0]; }
      else if (p.in === "header") v = req.headers[p.name.toLowerCase()];
      else continue;
      if (v === undefined) { if (p.required) errors.push(`${p.in} parameter ${p.name}: required`); continue; }
      const s = deref(root, p.schema) || {};
      const val = Array.isArray(v) ? v.map((x) => coerce(root, s.items || {}, x)) : coerce(root, s, v);
      check(root, s, val, `${p.in} parameter ${p.name}`, errors);
      if (p.in === "query") query[p.name] = val;
    }
    const rb = deref(root, route.op.requestBody);
    let body;
    if (rb) {
      const ct = String(req.headers["content-type"] || "").split(";")[0].trim();
      if (!raw.length) { if (rb.required) errors.push("request body: required"); }
      else {
        const media = rb.content?.[ct] || Object.entries(rb.content || {}).find(([k]) => mediaKind(k) === mediaKind(ct))?.[1];
        if (!media) errors.push(`request body: content type ${ct || "(none)"} not accepted (${Object.keys(rb.content || {}).join(", ")})`);
        else if (mediaKind(ct) === "json") { try { body = JSON.parse(raw.toString("utf8")); if (media.schema) check(root, media.schema, body, "body", errors); } catch { errors.push("request body: invalid JSON"); } }
        else if (mediaKind(ct) === "multipart") { body = { multipart: true, bytes: raw.length }; const s = deref(root, media.schema); for (const r of s?.required || []) if (!raw.includes(Buffer.from(`name="${r}"`))) errors.push(`body.${r}: required`); }
        else body = raw.toString("utf8");
      }
    }
    const responses = route.op.responses || {};
    const want = String(req.headers["x-mock-status"] || (/code=(\d{3})/.exec(String(req.headers.prefer || "")) || [])[1] || "");
    let status = errors.length ? "400" : want && responses[want] ? want : Object.keys(responses).find((k) => /^2\d\d$/.test(k)) || Object.keys(responses).find((k) => /^2XX$/i.test(k)) || "default";
    const call = { method: req.method, path: url.pathname, operationId: route.op.operationId, pathParams, query, headers: req.headers, body, errors, status: Number(status) || 200 };
    calls.push(call);
    if (errors.length) { log(`${req.method} ${url.pathname} → 400 ${errors.join("; ")}`); return send(400, { code: "mock_invalid_request", message: "Request does not match the OpenAPI spec", errors }); }
    const resp = deref(root, responses[status]) || {};
    const code = status === "default" || /XX/i.test(status) ? (status === "default" ? 200 : Number(status[0]) * 100) : Number(status);
    const entries = Object.entries(resp.content || {});
    const accept = String(req.headers.accept || "");
    const [ct, media] = (/json/.test(accept) && entries.find(([k]) => mediaKind(k) === "json")) || entries.find(([k]) => accept.includes(k)) || entries[0] || [];
    if (!ct || code === 204) { call.response = undefined; log(`${req.method} ${url.pathname} → ${code}`); res.writeHead(code, { "Access-Control-Allow-Origin": "*" }); return res.end(); }
    let out = mediaExample(root, media);
    if (out && typeof out === "object" && out.__blob) out = "binary-example";
    call.response = out;
    log(`${req.method} ${url.pathname} → ${code}`);
    return send(code, out, ct);
  };
  return { handler, calls, routes };
}

export function startMock(spec, port = 4010, host = "127.0.0.1", opts = {}) {
  const mock = createMock(spec, opts);
  const server = createServer((req, res) => { mock.handler(req, res).catch((e) => { res.writeHead(500); res.end(String(e?.message || e)); }); });
  return new Promise((ok) => server.listen(port, host, () => ok({ ...mock, server, port: server.address().port, close: () => new Promise((d) => { server.close(() => d()); server.closeAllConnections?.(); }) })));
}
